/// Signed area of a closed path (shoelace formula), matching Clipper2Lib::Area.
/// Positive for counter-clockwise orientation (Cartesian, y-up).
pub fn area(path: &Path64) -> f64 {
    let n = path.len();
    if n < 3 {
        return 0.0;
    }
    let mut a: f64 = 0.0;
    for i in 0..n {
        let j = if i + 1 == n { 0 } else { i + 1 };
        a += path[i].x as f64 * path[j].y as f64 - path[j].x as f64 * path[i].y as f64;
    }
    a * 0.5
}

/// Bounding box of all points in `paths`, matching Clipper2Lib::GetBounds.
pub fn get_bounds(paths: &Paths64) -> Rect64 {
    let mut r = Rect64 {
        left: i64::MAX,
        top: i64::MAX,
        right: i64::MIN,
        bottom: i64::MIN,
    };
    for path in paths {
        for pt in path {
            if pt.x < r.left {
                r.left = pt.x;
            }
            if pt.x > r.right {
                r.right = pt.x;
            }
            if pt.y < r.top {
                r.top = pt.y;
            }
            if pt.y > r.bottom {
                r.bottom = pt.y;
            }
        }
    }
    r
